// This computer's identifiers for the machine code (see license.hpp). What changes the code:
//  - macOS: IOPlatformUUID + serial number of the logic board — stable across macOS reinstalls and user
//    accounts; a logic-board replacement changes it.
//  - Windows: MachineGuid (HKLM\SOFTWARE\Microsoft\Cryptography, written by Windows Setup) + the serial number
//    of the system volume — a Windows reinstall or a reformat of the system drive changes it; hardware upgrades
//    (RAM, GPU, a second disk) do not.
//  - other systems: /etc/machine-id (regenerated by an OS reinstall).
#include "thcad/license/license.hpp"

#include <cstdio>
#include <fstream>
#include <string>
#include <vector>

#if defined(__APPLE__)
#include <CoreFoundation/CoreFoundation.h>
#include <IOKit/IOKitLib.h>
#elif defined(_WIN32)
#ifndef NOMINMAX
#define NOMINMAX
#endif
#include <windows.h>
#endif

namespace thcad::license {

namespace {

#if defined(__APPLE__)
std::string cfString(CFTypeRef v) {
  if (!v || CFGetTypeID(v) != CFStringGetTypeID()) return {};
  char buf[256];
  if (!CFStringGetCString(static_cast<CFStringRef>(v), buf, sizeof buf, kCFStringEncodingUTF8)) return {};
  return buf;
}

std::vector<std::string> identifiers() {
  std::vector<std::string> ids;
  io_service_t svc = IOServiceGetMatchingService(kIOMainPortDefault, IOServiceMatching("IOPlatformExpertDevice"));
  if (!svc) return ids;
  for (const char* key : {kIOPlatformUUIDKey, kIOPlatformSerialNumberKey}) {
    CFStringRef k = CFStringCreateWithCString(kCFAllocatorDefault, key, kCFStringEncodingUTF8);
    CFTypeRef v = IORegistryEntryCreateCFProperty(svc, k, kCFAllocatorDefault, 0);
    const std::string s = cfString(v);
    if (v) CFRelease(v);
    CFRelease(k);
    if (!s.empty()) ids.push_back(std::string("mac:") + key + "=" + s);
  }
  IOObjectRelease(svc);
  return ids;
}
#elif defined(_WIN32)
std::string utf8(const wchar_t* w) {
  const int n = WideCharToMultiByte(CP_UTF8, 0, w, -1, nullptr, 0, nullptr, nullptr);
  if (n <= 1) return {};
  std::string s(std::size_t(n - 1), '\0');
  WideCharToMultiByte(CP_UTF8, 0, w, -1, s.data(), n, nullptr, nullptr);
  return s;
}

std::vector<std::string> identifiers() {
  std::vector<std::string> ids;
  wchar_t guid[128] = {};
  DWORD size = sizeof guid;
  // the 64-bit view: a 32-bit process would otherwise read a redirected (missing) key
  if (RegGetValueW(HKEY_LOCAL_MACHINE, L"SOFTWARE\\Microsoft\\Cryptography", L"MachineGuid", RRF_RT_REG_SZ | RRF_SUBKEY_WOW6464KEY, nullptr, guid, &size) == ERROR_SUCCESS)
    ids.push_back("win:MachineGuid=" + utf8(guid));
  wchar_t winDir[MAX_PATH] = {};
  if (GetWindowsDirectoryW(winDir, MAX_PATH) >= 3) {
    wchar_t root[4] = {winDir[0], L':', L'\\', 0};
    DWORD serial = 0;
    if (GetVolumeInformationW(root, nullptr, 0, &serial, nullptr, nullptr, nullptr, 0)) {
      char buf[32];
      std::snprintf(buf, sizeof buf, "%08lX", static_cast<unsigned long>(serial));
      ids.push_back(std::string("win:SystemVolume=") + buf);
    }
  }
  return ids;
}
#else
std::vector<std::string> identifiers() {
  std::vector<std::string> ids;
  for (const char* path : {"/etc/machine-id", "/var/lib/dbus/machine-id"}) {
    std::ifstream f(path);
    std::string s;
    if (f && std::getline(f, s) && !s.empty()) {
      ids.push_back("unix:machine-id=" + s);
      break;
    }
  }
  return ids;
}
#endif

}  // namespace

std::string machineCode() { return machineCodeFromIdentifiers(identifiers()); }

}  // namespace thcad::license
